create table if not exists master_country(id serial not null,
country_name varchar(255) not null,
iso2 varchar(10),iso3 varchar(10),capital varchar(255),continent varchar(255),phone_code varchar(10),
is_active boolean default true,
constraint pk_master_country_id primary key(id),
constraint uk_master_country_country_name unique(country_name));

select string_agg(column_name,',') from information_schema.columns where table_name='master_country';

select setval('master_country_id_seq', (SELECT MAX(id)+1 FROM master_country));


select * from master_country;

create table if not exists master_state(id serial not null,
state_code integer not null,
state_version integer,state_name varchar(255) not null,
state_name_in_local varchar(255),										
country_id integer not null,
census_2001_code integer,census_2011_code integer,
state_or_ut char(1),
is_active boolean default true,
constraint pk_master_state_id primary key(id),
constraint fk_master_state_country_id foreign key(country_id) references master_country(id),
constraint uk_master_state_state_code unique(state_code));



select * from master_state;


select state_code,id from master_state;

create table if not exists master_district(id serial not null,
district_code integer not null,district_name varchar(255) not null,
state_id integer not null,
census_2001_code integer,census_2011_code integer,
is_active boolean default true,
constraint pk_master_district_id primary key(id),
constraint fk_master_district_state_id foreign key(state_id) references master_state(id),
constraint uk_master_district_district_code unique(district_code));


select * from master_district;

create table if not exists master_sub_district(id serial not null,
sub_district_code bigint,sub_district_version integer,sub_district_name varchar(255) not null,
district_id integer not null,
census_2001_code integer,census_2011_code bigint,
is_active boolean default true,
constraint pk_master_sub_district_id primary key(id),
constraint uk_master_sub_district_sub_district_code unique(sub_district_code),
constraint fk_master_sub_district_district_id foreign key(district_id) references master_district(id));

select * from master_sub_district;

call sp_copy_files('master_sub_district','E:\RM1 Coders Project Files\HIMS\master_sub_district.csv');

create table if not exists master_village(id bigserial not  null,
village_code bigint not null,village_version integer,village_name varchar(255) not null,
sub_district_id integer not null,census_2001_code bigint,census_2011_code bigint,
is_active boolean default true,
constraint pk_master_village_id primary key(id),
constraint fk_master_village_sub_district_id foreign key(sub_district_id) references master_sub_district(id),
constraint uk_master_village_village_code unique(village_code));

select sub_district_code,id from master_sub_district;


